import os
import stat
import sys


def sanitize_descriptors():
    for fd in range(3):
        try:
            kind = os.fstat(fd).st_mode
        except OSError:
            os._exit(126)
        if not (stat.S_ISREG(kind) or stat.S_ISFIFO(kind) or stat.S_ISCHR(kind)):
            if fd != 2 and not stat.S_ISSOCK(os.fstat(2).st_mode):
                os.write(2, b"refusing nonlocal/socket standard stream\n")
            os._exit(126)
    closed = []
    for name in os.listdir("/proc/self/fd"):
        fd = int(name)
        if fd >= 3:
            try:
                kind = os.fstat(fd).st_mode
                os.close(fd)
                closed.append({"fd": fd, "socket": stat.S_ISSOCK(kind), "regular": stat.S_ISREG(kind)})
            except OSError:
                pass  # /proc enumeration's descriptor has already closed.
    for name in os.listdir("/proc/self/fd"):
        fd = int(name)
        if fd >= 3:
            try:
                os.fstat(fd)
            except OSError:
                continue
            os._exit(126)

    return closed


